        text: 'Buradaki en önemli ayrım şu: gürültü, "bozuk" bir şey değildir. Ölçtüğünüz şeyin kendisinden gelir. Kusursuz bir kamerayla, kusursuz bir gecede, kusursuz bir teleskopla çekseniz bile foton gürültüsü orada olacaktır — çünkü ışığın kendisi tanecikli.',
