        text: 'Hedeften gelen ışığın tanecikliliği. Poz süresiyle doğrusal büyüyen sinyalin karekökü kadardır. **Kaçınılmazdır** — ve iyi haber şu ki bu, gürültüyle mücadelenin bittiği yerdir. Diğer bütün kaynakları sıfırlasanız bile bu kalır; amacınız zaten "foton gürültüsü sınırlı" duruma ulaşmaktır.',
