        type: 'paragraph',
        text: 'Gökyüzünün kendisi de bir ışık kaynağıdır: ışık kirliliği, ay, atmosferin doğal ışıması, hatta zodyak ışığı. Bu ışık hedefinizin üstüne biner. Ortalamasını kolayca çıkarabilirsiniz (gradyan giderme tam olarak bunu yapar) ama *gürültüsünü* çıkaramazsınız. Şehirden çekim yapmanın asıl bedeli budur — kirlilik değil, kirliliğin karekökü.',
