        type: 'paragraph',
        text: 'Piksel içindeki yükü okuyup sayıya çeviren elektronik devrenin kendi belirsizliği. **Poz süresinden bağımsızdır**: bir saniyelik pozda da, on dakikalık pozda da aynıdır. Her kare için bir kez ödenir. Yani *çok sayıda kısa poz* çektiğinizde bu vergiyi çok kez ödersiniz. Alt poz süresi tartışmasının tamamı bu tek cümleden doğar.',
