        tone: 'info',
        text: 'Çünkü RASA yalnızca f-oranını düşürmez — açıklığı büyük tutarken odak uzaklığını kısaltır. 8″ RASA 200 mm açıklığa sahiptir; yani 200 mm f/10 bir SCT ile *aynı* sayıda foton toplar. Farkı, o fotonları çok daha az piksele yaymasıdır. Yaygın hedeflerde bu gerçek bir kazançtır, ayırma gücünde ise değildir.',
        title: "Öyleyse RASA'lar neden hızlı?",
