      'ZWO EFW 7×36 mm Mk II filtre çarkı · 269 $ · 515 g, 20 mm arka odak ekler',
      'Antlia 7 filtre seti (LRGB-V + 3 nm SHO) · 1.419 $ · 36 mm, çerçevesiz',
      '**Mono ek toplam** · **1.688 $** · Kameradan önce',
