      'Askar C1 + C2 (OSC "SHO" çifti) · 248 $ · İkisi birlikte',
      'Bağımsız tahminler mono kurulumun eşdeğer OSC kurulumunun **1,4 ilâ 2 katına** mal olduğunu söylüyor.',
      'Kalibrasyon yükü',
      'Genel kabul her filtre için ayrı flat çekmek yönünde — toz lekeleri ve ışık dağılımı her filtrede biraz farklı olur. Filtre başına 25 kare önerisiyle:',
      'Formül: Mono: 7 filtre × 25 =\n175 flat\n+ 7 master · Renkli:\n25 flat\n+ 1 master\n\nDar bant flat pozları bant genişliğine göre 45 ile 90+ saniye arasında sürer. MaxIm DL 5 ve üstü, FITS başlıkları elle düzenlenmediği sürece filtre başına flat zorunlu kılar.',
      'Not: **Karşı görüş:** deneyimli bir kullanıcı luminans flat\'lerini RGB verisine uyguladığında "gerçekten hiçbir fark göremediğini" bildiriyor. Kendi kurulumunuzda denemeye değer; işe yarıyorsa yükün büyük kısmı kalkar.',
      'Hava ve Ay',
      'Renkli kamera her karede tam renk bilgisi toplar. Bulut mono çekimi filtre ortasında keserse elinizde dengesiz kanal verisi kalır. Bu, açık gece sayısının az olduğu yerlerde ciddi bir avantajdır. Pratik kural olarak dolaşan formülasyon şu: *sınırlı açık gece renkliyi, istikrarlı koşullar monoyu kayırır* — ve bu coğrafyayla belirlenir.',
      "Ay tarafında ise mono kazanır, ama beklenmedik bir sebeple: dar bant filtreler Ay ışığını bloklar ve mono kullanıcısı hangi filtrenin ne kadar tolere ettiğini bilerek program yapabilir. Ay'a dayanıklılık sırası nettir: **H-alfa** en toleranslı, **SII** orta, **OIII** en kötü.",
      'Berkeley otomatik teleskop programının Ay kaçınma açıları',
