      'Not: **Filtre değişimi ne kadar süre kaybettirir? Kimse yayımlamıyor.** ZWO filtre çarkının değişim süresini açıklamıyor. NINA otomatik odak süresini belgelemiyor; süre adım sayısına, poz süresine ve işleme yüküne bağlı. İnternette dolaşan bütün "filtre değişimi şu kadar zaman kaybettirir" rakamları tahmindir. Gerçek çözüm zaten her filtrede odak yapmak değil, **filtre ofsetleri** kullanmaktır: odak konumundaki farkı önceden ölçer, filtre değişince odaklayıcıyı o kadar kaydırırsınız.',
      'Yıldız renkleri ve kalibrasyon',
      'Dual-band filtreyle çekilmiş bir dar bant görüntüde yıldızların garip renklerde çıkması bir işleme hatası değil, doğrudan fizik.',
