      "H-alfa'nın yeşil ve mavi piksellere %5–10 arası sızması durumu daha da bozar. Yan etkiler tanıdıktır: bazı yıldızların çevresinde kırmızımsı halkalar, kanallar arasında farklı yıldız boyutları, hizalama sorunları.",
      '**Standart çözümler:** (a) yıldızlar için ayrı bir geniş bant RGB seansı çekip yıldız katmanını oradan almak, (b) yıldızları ayırıp ayrı işleyip geri koymak, (c) yıldız kara cisim modeline göre PixelMath ile kanalları yeniden dağıtmak.',
      "SHO görüntülerde mor yıldızlar neden çıkar ve nasıl giderilir?: Hubble paletinde H-alfa yeşile, SII kırmızıya, OIII maviye eşlenir. Yıldızlar sürekli spektrumlu olduğu için hem kırmızı hem mavi kanalda güçlü kaydedilir; yeşilde ise nispeten zayıf kalırlar. Kırmızı + mavi = magenta.\nStandart çözüm zekicedir: görüntüyü tersine çevirin, yeşil bastırma (SCNR) uygulayın, sonra tekrar tersine çevirin. Magenta, yeşilin tersi olduğu için tersine çevrilmiş görüntüde yeşil olarak görünür ve SCNR onu temizler — bulutsunun gerçek yeşil H-alfa yapısına dokunmadan.\nAlternatifler: PixelMath ile yıldızları yeniden renklendirmek veya yıldızları tamamen çıkarıp RGB'den gelen bir yıldız katmanıyla değiştirmek.",
