      "Not: **En dürüst özet:** mono üstünlüğü sabit bir çarpan değil. Yalnızca RGB çekildiğinde renkli kamera %33 önde; eşit LRGB'de mono %17 önde; luminans ağırlıklı planda mono 2,3 kat önde. Yani **nasıl çektiğiniz, hangi kamerayı aldığınız kadar önemli**. Bu cümle, tartışmanın mono tarafından gelen kaynağın kendi sonucudur.",
      "Renkli kameram var, monoya geçmeden yapabileceklerim neler?: **Her zaman dither yapın.** CFA drizzle'ın çalışması buna bağlı ve maliyeti kare başına birkaç saniye.\n**Drizzle ile yığın, VNG kullanmayın.** Hem çözünürlük hem fotometrik doğruluk için.\n**Dual-band filtre alın, ama beklentinizi ayarlayın.** H-alfa + OIII için gerçek bir kazanç; SHO için değil.\n**Yıldızlar için ayrı geniş bant seans çekin.** Bir saatlik RGB verisi, dual-band görüntünün yıldız renklerini kurtarmaya yeter.\n**Toplam süreyi artırın.** Renkli kameranın açığını kapatmanın en basit yolu, üstteki ilk aracın söylediği kadar fazla saat çekmek. Genelde bu, ikinci bir kamera almaktan hem ucuz hem kolaydır.",
