          'Madratter — [Does Mono Take More Time?](https://astroimages.weebly.com/does-mono-take-more-time.html) · Cosgrove — [OSC vs Mono](https://cosgrovescosmos.com/tips-n-techniques/osc-vs-mono-which-is-best)',
          'Atik — [Sony IMX571 Complete Technical Guide](https://www.atik-cameras.com/news/sony-imx571-sensor-complete-technical-guide/)',
