      'Hata neye benzer: iki bileşen',
      'Hizalama hatası tek bir sayı değildir. Ekseniniz gök kutbundan iki bağımsız yönde sapabilir: **azimut** (doğu–batı) ve **yükseklik** (kuzey–güney). Montürünüzde iki ayrı ayar vidası olmasının ve yazılımların size iki ayrı sayı bildirmesinin sebebi budur.',
      'Şekil: İki Bilesen: Kaynak pakette iki-bilesen adlı şekil/şema yer tutucusu vardı.',
