      'Formül: Sürüklenme (yay sn/dk) =\n0,2625\n× hata (yay dakikası)\n\nTüretimi: ω = 902,5 yay sn/dk; 1 yay dakikası = 2,909×10⁻⁴ radyan; çarpımı 0,2625.',
      'Guiding olmadan, en kötü durumda',
      'Hizalama hatası · Sürüklenme · 5 dakikada · Bir saatte · Sonuç',
      '0,5′ (30″) · 0,13 ″/dk · 0,7″ · 7,9″ · Görünmez',
