      'pixfrac, ölçek ve gürültü korelasyonu',
      'Drizzle\'ın en yanlış anlaşılan yanı gürültüye etkisi. "Drizzle gürültüyü artırır" cümlesi doğru ama eksik — asıl mesele gürültünün *miktarı* değil, **karakteri**.',
