      'Formül: r = pixfrac × ölçek\n\nr ≥ 1 ise: R =\nr ⁄ (1 − 1/(3r))\n· r ≤ 1 ise: R =\n1 ⁄ (1 − r/3)\n\nR, piksel-piksel ölçülen gürültünün gerçek gürültüyü kaç kat **küçük** gösterdiğidir. R = 2,2 ise ölçüm aracınız gürültüyü gerçeğin yarısından az gösteriyor demektir.',
