      '2× · 0,2 · 0,40 · **1,15** · Korelasyon düşük ama **delik dolu çıktı** — R tek başına karar vermez',
      "Not: **SNR ölçüm araçları drizzle'lı görüntüde yalan söyler.** Drizzle çıktısını bir SNR/gürültü betiğiyle ölçüp \"gürültü azalmış\" derseniz yanılırsınız. Bu araçlar komşu piksel farklarına bakar; drizzle komşuları korele ettiği için ölçüm gerçeği **R kat** iyimser gösterir. PixInsight varsayılanlarında bu 2,2 kat demektir. Drizzle'lı ve drizzle'sız iki yığını sayısal SNR ile karşılaştırmak *geçersiz* bir karşılaştırmadır; göz kararı ve yıldız FWHM ölçümü daha güvenilirdir.",
      "Dithering: drizzle'ın yakıtı",
      'Şekil: Dither Faz: Kaynak pakette dither-faz adlı şekil/şema yer tutucusu vardı.',
      'Etkileşimli araç: Drizzle Lab: Kaynak pakette drizzle-lab adlı hesaplayıcı/etkileşimli araç yer tutucusu vardı. İçerik editöründe düzenlenebilir not olarak korunuyor.',
      'Not: **Alt piksel dither yapmaya çalışmayın.** Amatör kurulumda gereken şey kaymanın *kesirli kısmının* rastgele olmasıdır ve bu bedava gelir: yazılım ondalıklı bir sayı üretir, rehber kamera ile çekim kamerası arasındaki ölçek oranı neredeyse hiçbir zaman tam sayı değildir, guiding artıkları da fazladan rastgelelik katar. **10 piksellik bir dither, 0,5 piksellik bir dither ile tamamen aynı faz çeşitliliğini sağlar** — üstelik sabit desen gürültüsünü ve yürüyen gürültüyü de temizler. Birkaç piksel, rastgele. Yeterli.',
      "Dithering'in ayrıntıları ve oturma süresi bütçesi Guiding yazısında; oradaki üçüncü araç dither miktarını rehber pikselinden çekim pikseline çeviriyor ve gece kaybınızı hesaplıyor.",
      'Bayer / CFA drizzle: renkli kameralar için',
      "Renkli bir kameranız varsa bu bölüm muhtemelen sizin için klasik drizzle'dan daha değerli.",
      'Renkli sensörde her fotositin önünde tek bir renk filtresi vardır. Yani her piksel için üç renk değerinden **ikisi hiç ölçülmemiştir**; debayer algoritması onları komşulardan *tahmin eder*. Bu tahmin fena değildir ama bedava değildir: kenarlarda sahte renkler, ince yapılarda "fermuar" ve labirent desenleri, arka planda debayer\'ın kendi imzasını taşıyan yapılı gürültü.',
      'CFA drizzle bu tahmini ortadan kaldırır: ölçülmüş renk değerlerini doğrudan çıktı ızgarasına çiseler. Farklı karelerde aynı gök noktasının üzerine farklı renk filtreleri düştüğü için, üç kanal da *ölçülmüş* veriyle dolar.',
      'Not: **Geri dönüşü yok: debayer edilmiş veriye CFA drizzle uygulanamaz.** Bir kere debayer yaptıysanız, tahmin edilmiş değerler ölçülmüş olanlardan ayırt edilemez hale gelir. İş akışının en başında karar vermeniz gerekir: **kalibre edin, ama debayer etmeyin.** CFA deseni drizzle girdisine kadar korunmalıdır.',
      'Yazılım bazında CFA drizzle ayarları',
