      "**PixInsight** · Enable CFA drizzle · Scale **1**, Drop shrink **1,00**, kernel **Square**. WBPP'de ayrı kutu yok: Calibration'da *CFA images*, Post-Calibration'da *Drizzle* işaretleyin",
      '**Siril 1.4+** · Bayer Drizzle · Kalibrasyonda **"Debayer before saving" işaretini kaldırın**. Sonra scale = pixfrac = **1,0**. Yığınlamada MAD Clipping elemesi',
      '**APP** · Integration mode: Bayer Drizzle · scale **1,0**, drops **2,0**, kernel **tophat**',
      '**ASTAP** · Stack method · Tek kalan drizzle türü. Çok kare gerekir',
      '**DSS** · RAW/FITS debayer seçeneği · Normal Drizzle ile **birlikte kullanmayın**',
      'Not: **Beklentiyi doğru kurun.** Siril\'in belgeleri, amatör pazarlamasının aksine alışılmadık derecede dürüst: *"Kullanıcılar, sonuçları debayer edilmiş yığınlanmış görüntülerle karşılaştırdıklarında sonuçları hayal kırıklığı yaratıcı bulabilir. Genellikle kazanç vardır, ancak marjinal olabilir (örneğin FWHM\'de birkaç yüzdelik iyileşme)."*\n\nÖyleyse CFA drizzle\'ın gerçek getirisi ne? **Gürültü karakteri ve artefakt temizliği.** Siril\'in ifadesiyle drizzle\'lı sonuçta gürültü *"çok daha temiz"* ve *"tipik bir debayer edilmiş CFA yığınının arka planında görülen yapıdan yoksun"*.',
      "**Neden CFA'da ölçek = 1?** Çünkü kırmızı ve mavi kanallar sensörün yalnızca %25'ini kaplar. Ölçeği 2×'e çıkarmak, zaten seyrek olan bu kanallarda kapsama açığını dörde katlar. Bütün paketler bu yüzden CFA için 1× üzerinde birleşiyor.",
