      '**APP** Bayer Drizzle · Evet · En dürüst uyarıları veren paket',
      '**ASTAP** · Sadece CFA · Normal drizzle **kaldırıldı**; geliştirici geri getirmeyeceğini açıkladı',
      '**DeepSkyStacker** · Hayır · "Süper-örnekle sonra yığınla" yapıyor; pixfrac yok, kernel yok, ağırlık haritası yok',
      'PixInsight DrizzleIntegration: üç aşamalı iş akışı ve kernel seçimi: **1 · StarAlignment** (veya WBPP kaydı), *"Generate drizzle data"* açık → her kare için bir `.xdrz` dosyası yazılır.\n**2 · ImageIntegration** normal şekilde çalıştırılır → `.xdrz` dosyalarının *içine* kare ağırlıkları, eleme maskeleri ve normalizasyon verisi geri yazılır. **Bu adım zorunludur**; atlarsanız DrizzleIntegration ağırlıklandırma ve eleme yapamaz.\n**3 · DrizzleIntegration** görüntüleri değil, `.xdrz` dosyalarını alır ve master\'ı üretir.\n**Truncate on out-of-range ayarının kapalı olduğundan emin olun** — açıksa doymuş yıldız çekirdekleri *siyah* çıkabilir.\n**Kernel seçimi — folklorla ölçüm çelişiyor.** Forumlarda "Circular daha keskin yıldız verir" denir. 16 alt kareli ölçümlü bir testte (2× drizzle, 0,9 drop) sonuç şuydu: drizzle yok 2,590e-4 · **Square 1,511e-4 (en iyi, hem en hızlı hem en düşük gürültü)** · Circular 2,015e-4 (daha yavaş *ve* daha gürültülü) · Gaussian 2,580e-4 (drizzle yapmamakla neredeyse aynı). Bu tek bir test — ama Square\'in varsayılan olmasının bir sebebi var. Gaussian ayrıca **akı korumalı değildir**; fotometri yapacaksanız Square kullanın.',
